// Curriculum types mirror docs/curriculum-v2.types.ts; the rest is in docs/CONTENT_SCHEMA.md — keep in sync.

// ── Curriculum (content/curriculum.json, version 2) ──────────────────────────
// Mirrors docs/curriculum-v2.types.ts; generated by scripts/build_curriculum.py.
export type Difficulty = "Easy" | "Medium" | "Hard";
export type Platform = "LeetCode" | "HackerRank";

/**
 * core      — a problem for this week's topic
 * old-topic — a problem from an earlier week; the UI must hide `fromWeek` and the week's topic
 * fallback  — shown only when the redo queue is empty; never counts toward day status
 * pool      — spare problem; feeds mock Program 1 and free practice
 */
export type ProblemRole = "core" | "old-topic" | "fallback" | "pool";

export interface Problem {
  id: string;            // "w03-d2-p1", "w03-d7-fb", "w03-pool-04" — stable, never reuse
  platform: Platform;
  lcNumber?: number;     // real LeetCode problem number (v1 used it for roadmap position)
  title: string;
  difficulty: Difficulty;
  url: string;
  role: ProblemRole;
  fromWeek?: number;     // old-topic only
}

export type DayKind =
  | "new-topic"      // Day 1: cold try, then concepts + templates
  | "topic"          // practice on this week's topic
  | "python-fluency" // Week 1 Day 4: HackerRank Python
  | "old-topics"     // unlabelled problems from earlier weeks
  | "timed"          // 45 min per problem
  | "redo"           // redo queue first, fallback if empty
  | "wrap-up";       // Week 13 Day 6

export type MockExtra = "debug" | "explain-aloud" | "complexity-check";

export interface MockSlot {
  number: number;        // 1–45
  pythonTheme: number;   // 1–15, index into mockSpec.pythonThemes
  extra: MockExtra;
  program2: boolean;     // even-numbered mocks and Mock 45
  diagnostic: boolean;   // Mock 1
  final: boolean;        // Mock 45
  mcqCount: number;      // 18 (20 for the final)
}

export interface PlanDay {
  day: 1 | 2 | 3 | 4 | 5 | 6 | 7;
  planDay: number;       // 1–90, position in the plan ignoring extensions
  kind: DayKind;
  mock: MockSlot | null; // non-null when planDay is odd; extension days never have one
  learn: string | null;  // learn item label; null = no learn item that day (coding only)
  problems: Problem[];   // counted toward day status
  fallback: Problem | null;
  timedMinutes: number | null;
  codingNote: string | null;
}

export interface Week {
  week: number;          // 1–13 (Week 13 has 6 days)
  title: string;
  goal: string;
  concepts: string[];
  visuals: string[];
  templates: string[];
  days: PlanDay[];
  pool: Problem[];
  problemCount: number;  // core problems
  oldTopicCount: number;
  mockCount: number;
}

export interface MockPart {
  part: "A" | "B" | "C" | "D";
  name: string;
  minutes: number;
  mix?: { python: number; currentAndLastWeek: number; spacedReview: number };
  source?: string;
  when?: string;
  rotation?: MockExtra[];
}

export interface MockSpec {
  rule: string;
  parts: MockPart[];
  pythonThemes: { id: number; title: string }[];
}

export interface PracticalTask {
  id: string;            // "pt-01"
  title: string;
  levels: [string, string, string];
  unlockWeek: number;    // first week a mock may use it
}

export interface Curriculum {
  version: 2;
  defaultStartDate: string; // YYYY-MM-DD
  totalPlanDays: number;    // 90
  mockSpec: MockSpec;
  practicalTasks: PracticalTask[];
  weeks: Week[];
}

// ── Questions (content/questions/week-NN.json) ───────────────────────────────
export type QuestionType = "pattern" | "complexity" | "output" | "bug" | "approach" | "concept";

export interface Question {
  id: string; // "w01-q07" — stable, never reuse
  week: number;
  type: QuestionType;
  pattern: string; // e.g. "Sliding Window", used by the dashboard
  difficulty: "medium" | "hard"; // interview level
  prompt: string; // markdown allowed
  code?: string; // Python 3.11
  options: string[]; // 4 options
  answer: number; // index into options
  explanation: string; // why, incl. time/space when relevant
  complexity?: { time: string; space: string };
  visual?: { component: string; props: Record<string, unknown> }; // optional diagram
  tags?: string[];
  theme?: number; // 1–15; set on Python-theme questions (ids "t01-q07")
}

export interface DrillPrompt {
  id: string; // "w03-dr04"
  week: number;
  description: string; // 1–3 sentence problem statement, no title
  answer: string; // pattern name
  distractors: string[]; // 5 other pattern names
}

// ── Mock content (content/practical/pt-NN.json, content/mock-extras/debug.json) ─
export interface PracticalLevel {
  level: 1 | 2 | 3;
  title: string;
  prompt: string;
  signature: string;
  sampleInput: string;
  expectedOutput: string;
  edgeCases: string[];
}

export interface PracticalTaskContent {
  id: string; // "pt-01"
  title: string;
  unlockWeek: number;
  intro: string;
  rules: string[];
  levels: [PracticalLevel, PracticalLevel, PracticalLevel];
}

export interface DebugSnippet {
  id: string; // "dbg-01"
  title: string;
  topic: string;
  week: number;
  code: string;
  bugLine: number; // 1-based line in `code`
  bug: string;
  fix: string;
  fixedCode: string;
  expected: string;
  actual: string;
  explanation: string;
}

export interface QuestionFile {
  week: number;
  theme?: number;
  questions: Question[];
  drill?: DrillPrompt[];
}

// ── Progress (Dexie / IndexedDB) ─────────────────────────────────────────────
// Completions belong to plan items, not dates, so extensions can move dates safely.
export interface ItemCompletion {
  itemId: string; // primary key: a problem id ("w03-d2-p1"), "w03-d2:learn", or a slot "w03-d7:s1" / "w03-x1:s1"
  planDayId: string; // "w03-d2" or extension day "w03-x1"
  completedOn: string; // YYYY-MM-DD when actually done
  attemptId?: number; // the ProblemAttempt that produced this completion (lets "untick" undo it)
}

export interface WeekExtension {
  id?: number;
  week: number;
  extraDays: number; // 1–14 total per week (sum of all extensions for that week)
  reason?: string;
  createdOn: string; // YYYY-MM-DD
}

// Computed in lib/schedule.ts, never stored:
export interface ScheduledDay {
  planDayId: string; // "w03-d2" | "w03-x1"
  week: number;
  kind: "plan" | "extension";
  date: string; // YYYY-MM-DD from startDate + preceding days + extensions
}

export interface ProblemAttempt {
  id?: number;
  problemId: string;
  date: string;
  outcome: "alone" | "hint" | "solution" | "failed";
  minutes: number;
  note?: string;
  isRedo: boolean;
  /** "mock": made during a mock. Never ticks a plan item and never counts toward a day's problems. */
  source?: "mock";
}

export interface RedoTask {
  id?: number;
  problemId: string;
  dueOn: string;
  doneOn?: string; // closed as completed (re-solved alone)
  attemptedOn?: string; // closed as attempted (hint/solution): a fresh redo chain replaced it
  createdByAttemptId?: number;
  closedByAttemptId?: number;
}

// Added in Dexie schema v2 (SPEC 3.13, 3.14)
export interface CustomItem {
  id: string; // "c-<uuid>"; used as itemId in completions and problemId in attempts/redos
  planDayId?: string; // day it belongs to ("w03-d2" or "w03-x1"); omitted = journal-only "found" problem
  week: number; // topic week, for filtering
  kind: "problem" | "task";
  platform?: string; // "LeetCode" | other; problems only
  title: string;
  difficulty?: Difficulty; // problems only
  url?: string;
  createdOn: string;
}

export interface ItemMove {
  itemId: string; // primary key: plan item id that was moved
  fromPlanDayId: string;
  toPlanDayId: string; // same week or its extension days
  movedOn: string;
}

// Journal data for ANY problem (plan, custom or found).
export interface ProblemEntry {
  problemId: string; // primary key: plan problem id, or a CustomItem id ("c-…")
  description?: string; // markdown
  approach?: string; // markdown
  code?: string; // Python
  timeComplexity?: string;
  spaceComplexity?: string;
  insight?: string; // key insight / what I missed
  comments?: string;
  confidence?: 1 | 2 | 3 | 4 | 5;
  tags: string[]; // pattern tags
  updatedOn: string;
}

export interface DayLog {
  planDayId: string; // primary key
  notes: string; // markdown
  minutes: number;
  links: string[];
  updatedOn: string;
}

export interface QuizAnswer {
  id?: number;
  questionId: string;
  correct: boolean;
  answeredAt: string; // ISO timestamp
  mode: "weekly" | "review" | "targeted" | "drill" | "mock"; // the first four only exist in data saved before v2
  ms?: number; // time to answer (drill)
  mockNumber?: number; // set when mode is "mock", so the dashboard can skip the diagnostic mock
}

export interface CardState {
  questionId: string;
  box: 1 | 2 | 3 | 4 | 5;
  dueOn: string;
}

export interface RestDay {
  date: string;
}

export interface MockProgram {
  part: 1 | 2;
  problemId: string; // Program 1: a problem id; Program 2: a practical task id ("pt-02")
  outcome: "alone" | "hint" | "solution" | "failed";
  minutes: number;
  levelsDone?: number; // Program 2 only
  skipped?: boolean;
}

/** A finished mock. Saving it ticks the "Mock N" row. */
export interface MockSession {
  id?: number;
  mockNumber: number;
  date: string; // YYYY-MM-DD actually taken
  diagnostic: boolean; // copied from the curriculum's mock.diagnostic at save time
  mcq: { total: number; correct: number; byType: Record<string, { total: number; correct: number }> };
  questionIds: string[];
  programs: MockProgram[];
  extra: { kind: MockExtra; done: boolean; snippetId?: string };
  rating: 1 | 2 | 3 | 4 | 5;
  notes?: string;
}

/** What a started mock will show, picked once so a reload does not reshuffle. Cleared when the session is saved. */
export interface MockRun {
  mockNumber: number; // primary key
  startedOn: string;
  questionIds: string[];
  groups: { theme: number; current: number; review: number };
  program1: { problemId: string | null; note?: string };
  program2: { taskId: string | null } | null;
  extra: { kind: MockExtra; snippetId?: string };
  /** Answers given so far, in question order (true = correct). */
  answers: boolean[];
  phase: "A" | "B" | "C" | "D" | "end";
  programs: MockProgram[];
  extraDone: boolean;
}

export interface Settings {
  id: "settings";
  startDate: string;
  theme: "light" | "dark" | "system";
}
